  static Bounds VisibleBounds(Renderer[] renderers,Bounds fallback){bool found=false;var b=fallback;foreach(var r in renderers){if(r==null||!r.enabled||!r.gameObject.activeInHierarchy||r.transform.lossyScale.sqrMagnitude<=1e-8f||r.bounds.size.sqrMagnitude<=1e-8f)continue;if(!(r is MeshRenderer)&&!(r is SkinnedMeshRenderer))continue;if(!found){b=r.bounds;found=true;}else b.Encapsulate(r.bounds);}return b;}
