  static Frame Snapshot(Fixture f,string label,int width,int height,Camera captureUi=null){var m=f.match;var cameras=(Camera[])Get(m,"cameras");var views=Get(m,"drivingViews");var rally=Get(views,"rally");var owners=(int[])Get(rally,"owners");var broadcast=(Component)Get(m,"broadcast");var framing=broadcast.GetComponent(Sports("SportsBroadcastFraming"));Assert.That(framing,Is.Not.Null);var frame=new Frame{label=label,clock=(float)Get(f.rules,"Clock"),unityFog=RenderSettings.fog,unityFogDensity=RenderSettings.fogDensity};frame.cameras=new World[cameras.Length];for(int v=0;v<cameras.Length;v++){var c=cameras[v];var effect=c.GetComponent(Type.GetType("LWS.TruckBogSnorkelling.BogCameraEffects, Assembly-CSharp",true));var water=(Transform)Get(effect,"waterSurface");float savedAspect=c.aspect,ortho=c.orthographicSize;var pos=c.transform.position;var rot=c.transform.rotation;try{if(captureUi!=null){c.aspect=width*c.rect.width/(height*c.rect.height);var fit=c.GetComponent(Sports("SportsCameraFit"));if(fit!=null)Call(fit,"Apply");}var props=(MaterialPropertyBlock)Get(effect,"Properties");var row=new World{view=v,owner=(bool)Get(views,"NeedsArena")?(int)Get(framing,"Primary"):owners[v],label=label,targetWidth=width,targetHeight=height,screenWidth=Screen.width,screenHeight=Screen.height,cameraPosition=c.transform.position,cameraRotation=c.transform.rotation,cameraRect=c.rect,aspect=c.aspect,fov=c.fieldOfView,orthographic=c.orthographic,cullingMask=c.cullingMask,waterY=water.position.y,cameraBelowWater=c.transform.position.y<water.position.y-.15f,underwater=(bool)Get(effect,"Underwater"),insideWaterBounds=((Bounds)Get(effect,"waterBounds")).Contains(c.transform.position),bogAppliedFrames=(int)Get(effect,"AppliedFrames"),bogTargetWidth=(int)Get(effect,"TargetWidth"),bogTargetHeight=(int)Get(effect,"TargetHeight"),submersion=props!=null?props.GetFloat("_BogSubmersion"):0,shotReason=(string)Get(framing,"ShotReason"),ownsShot=(bool)Get(framing,"OwnsShot")};var additional=c.GetComponent(Type.GetType("UnityEngine.Rendering.Universal.UniversalAdditionalCameraData, Unity.RenderPipelines.Universal.Runtime",true));row.depthRequested=(bool)Get(additional,"requiresDepthTexture");row.colorRequested=(bool)Get(additional,"requiresColorTexture");row.densityScale=(float)Get(effect,"densityScale");float density=(.047f+Mathf.Min(Mathf.Max(0,water.position.y-c.transform.position.y),4)*.004f)*row.densityScale;row.fogDensityApproxAt20m=Mathf.Min(.91f,1-Mathf.Exp(-20*density));row.fogDensityApproxAt40m=Mathf.Min(.91f,1-Mathf.Exp(-40*density));row.subjects=new Subject[4];for(int i=0;i<4;i++){var full=(Bounds)Call(framing,"TruckBounds",i);var host=Get(f.trucks[i],"appearanceHost");var renderers=(Renderer[])Get(host,"ExteriorRenderers");var body=VisibleBounds(renderers,((Collider)Get(f.trucks[i],"shape")).bounds);row.subjects[i]=Project(c,full,body,i);}frame.cameras[v]=row;if(v==0){var ocean=water.GetComponent<Renderer>();frame.oceanBounds=ocean.bounds;var mat=ocean.sharedMaterial;frame.oceanFogDensity=mat.HasProperty("_Fog_Density")?mat.GetFloat("_Fog_Density"):-1;frame.oceanRefraction=mat.HasProperty("_Refraction")?mat.GetFloat("_Refraction"):-1;frame.oceanBaseColor=mat.HasProperty("_BaseColor")?mat.GetColor("_BaseColor"):Color.white;}}finally{c.aspect=savedAspect;c.orthographicSize=ortho;c.transform.SetPositionAndRotation(pos,rot);}}
   var menus=(Component)Get(m,"menus");var canvas=menus.GetComponent<Canvas>();var panels=(RectTransform[])Get(menus,"viewPanels");var cards=new List<Hud>();for(int v=0;v<panels.Length;v++){var card=panels[v].Find("Compact owned viewport score") as RectTransform;if(card==null||!card.gameObject.activeInHierarchy)continue;var ui=captureUi!=null?captureUi:canvas.renderMode==RenderMode.ScreenSpaceOverlay?null:canvas.worldCamera;var pixel=Pixels(card,ui);int targetW=captureUi!=null?width:Screen.width,targetH=captureUi!=null?height:Screen.height;cards.Add(new Hud{view=v,owner=owners[v],label=label,anchor=card.anchorMin,pivot=card.pivot,position=card.anchoredPosition,size=card.sizeDelta,parentRect=panels[v].rect,pixelRect=pixel,normalizedRect=new Rect(pixel.x/targetW,pixel.y/targetH,pixel.width/targetW,pixel.height/targetH),viewport=cameras[v].rect,canvasScale=canvas.scaleFactor,referenceResolution=(Vector2)Get(canvas.GetComponent(Type.GetType("UnityEngine.UI.CanvasScaler, UnityEngine.UI",true)),"referenceResolution"),screenWidth=Screen.width,screenHeight=Screen.height,targetWidth=targetW,targetHeight=targetH,labels=card.GetComponentsInChildren(Type.GetType("TMPro.TMP_Text, Unity.TextMeshPro",true),true).Cast<Component>().Where(t=>t.gameObject.activeInHierarchy).Select(t=>new LabelBounds{name=t.name,text=(string)Get(t,"text"),pixels=Pixels((RectTransform)t.transform,ui),fontSize=(float)Get(t,"fontSize"),overflow=(bool)Get(t,"isTextOverflowing")}).ToArray()});}frame.cards=cards.ToArray();var presenter=menus.GetComponentInChildren(Sports("SportsScorePresentation"),true);if(presenter!=null){var notification=(Component)Get(presenter,"notification");var mask=notification.transform.Find("Mask Content");var accent=(Component)Get(presenter,"accent");frame.notificationAlpha=((CanvasGroup)Get(presenter,"visibility")).alpha;frame.heatMaskAlpha=mask.GetComponent<CanvasGroup>().alpha;frame.accentOutsideMask=!accent.transform.IsChildOf(mask);frame.accentInheritedAlpha=((CanvasRenderer)G