  static void CaptureDiagnostic(Fixture f,List<Frame> frames,string dir,string name,int w,int h){var save=Sports("SportsControlledCapture").GetMethods().Single(m=>m.Name=="Save"&&m.GetParameters().Length==5&&m.GetParameters()[0].ParameterType.IsInstanceOfType(f.match));string path=Path.Combine(dir,"controlled-"+name+"-"+w+"x"+h+".png");Action<Camera> inspect=ui=>frames.Add(Snapshot(f,name+"-during-explicit-capture",w,h,ui));save.Invoke(null,new object[]{f.match,w,h,path,inspect});var image=new Texture2D(2,2);try{Assert.That(image.LoadImage(File.ReadAllBytes(path)),Is.True);Assert.That(new Vector2Int(image.width,image.height),Is.EqualTo(new Vector2Int(w,h)));}finally{UnityEngine.Object.DestroyImmediate(image);}}
  static void Persist(List<Frame> frames,string dir){File.WriteAllText(Path.Combine(dir,"presentation.json"),JsonUtility.ToJson(new Report{frames=frames.ToArray()},true));}
  static void ValidateCards(Frame frame,int count){Assert.That(frame.cards.Length,Is.EqualTo(count));foreach(var card in frame.cards){Assert.That(card.owner,Is.EqualTo(card.view));Assert.That(card.anchor,Is.EqualTo(new Vector2(0,1)));var v=card.viewport;var r=card.normalizedRect;Assert.That(r.xMin,Is.GreaterThanOrEqualTo(v.xMin-.001f));Assert.That(r.xMax,Is.LessThanOrEqualTo(v.xMax+.001f));Assert.That(r.yMin,Is.GreaterThanOrEqualTo(v.yMin-.001f));Assert.That(r.yMax,Is.LessThanOrEqualTo(v.yMax+.001f));Assert.That(card.labels.Any(t=>t.overflow),Is.False,"Actual typed names/score/depth/health/context must fit without overflow.");}}
  [UnityTest,Timeout(75000)]public IEnumerator NaturalOneThroughFourChaseOwnersFitWithLocalCardsClearerWaterSharedAndCabPreserved(){using(var f=new Fixture()){yield return f.Load();var views=Get(f.match,"drivingViews");var rally=Get(views,"rally");Assert.That((Vector3)Get(rally,"groundOffset"),Is.EqualTo(new Vector3(0,4.5f,-24)));Assert.That((float)Get(rally,"groundLookAhead"),Is.EqualTo(2));Sports("SportsCameraOptions").GetMethod("Set").Invoke(null,new object[]{true});var frames=new List<Frame>();string dir="Logs/TruckSports/PlaytestRepair/SubmarineReadablePresentationNative/"+CaptureId;Directory.CreateDirectory(dir);for(int n=1;n<=4;n++){Call(views,"Select",1);f.Start(n);Time.timeScale=2;float deadline=Time.realtimeSinceStartup+10;while((float)Get(f.rules,"Clock")<8&&Time.realtimeSinceStartup<deadline)yield return null;Time.timeScale=1;yield return null;yield return null;var shot=Snapshot(f,"natural-chase-"+n,Screen.width,Screen.height);frames.Add(shot);Persist(frames,dir);ValidateCards(shot,n);foreach(var camera in shot.cameras){Assert.That(camera.subjects[camera.owner].cornersInside,Is.EqualTo(8),"Actual complete composed owner hull must fit its natural chase view.");}if(n==4){CaptureDiagnostic(f,frames,dir,"four-view",1280,720);CaptureDiagnostic(f,frames,dir,"four-view",1920,1080);Persist(frames,dir);ValidateCards(frames.Last(),4);Assert.That(frames.Last().cameras.All(c=>c.underwater&&c.bogAppliedFrames>0),Is.True);foreach(var camera in (Camera[])Get(f.match,"cameras")){var effect=camera.GetComponent(Type.GetType("LWS.TruckBogSnorkelling.BogCameraEffects, Assembly-CSharp",true));Assert.That((float)Get(effect,"densityScale"),Is.EqualTo(.35f));Assert.That(((MaterialPropertyBlock)Get(effect,"Properties")).GetFloat("_BogDensityScale"),Is.EqualTo(.35f));}}}Call(views,"Select",0);yield return null;yield return null;CaptureDiagnostic(f,frames,dir,"shared",1280,720);CaptureDiagnostic(f,frames,dir,"shared",1920,1080);Persist(frames,dir);var shared=frames.Last().cameras.Single();Assert.That(shared.subjects[shared.owner].cornersInside,Is.EqualTo(8));Assert.That(shared.subjects[shared.owner].bodyProjectedHeight,Is.GreaterThan(.12f));var mounts=((Transform[])Get(views,"cabMounts"))?.ToArray();var looks=((Array)Get(views,"looks")).Cast<object>().ToArray();Call(views,"Select",2);yield return null;yield return null;Assert.That(((Camera[])Get(f.match,"cameras")).All(c=>Mathf.Abs(c.fieldOfView-78)<.01f),Is.True,"Original cab lens/look pipeline remains original.");var after=(Transform[])Get(views,"cabMounts");Assert.That(after,Is.EqualTo(mounts));Assert.That(((Array)Get(views,"looks")).Cast<object>(),Is.EqualTo(looks));File.WriteAllText(Path.Combine(dir,"presentation.json"),JsonUtility.ToJson(new Report{frames=frames.ToArray()},true));TestContext.WriteLine("SUBMARINE_READABLE_CONTROLLED_NATIVE; direct720/1080 review and actual Windows acceptance remain required. Physics/rules/scoring unchanged.");}}
